<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { IconDownload, IconFileTypePdf, IconPresentation, IconRefresh, IconSparkles } from '@tabler/icons-vue'
import AppShell from '@/components/layout/AppShell.vue'
import ProjectTabs from '@/components/layout/ProjectTabs.vue'
import { api } from '@/api/services'
import type { ProposalDocument } from '@/api/contracts'

const route=useRoute();const proposal=ref<ProposalDocument|null>(null);const loading=ref(false);const activeSection=ref('s1');const view=ref<'outline'|'preview'>('preview')
