    <div class="proposal-layout">
      <aside class="outline tech-panel"><div class="panel-title"><span>方案大纲</span><span class="score">{{proposal?.sections.filter(s=>s.status!=='EMPTY').length}}/{{proposal?.sections.length}}</span></div><button v-for="section in proposal?.sections" :key="section.id" :class="{active:activeSection===section.id}" @click="activeSection=section.id"><span>{{section.title}}</span><i :class="section.status.toLowerCase()">{{section.status==='EMPTY'?'待生成':'已生成'}}</i></button></aside>
      <section class="slide tech-panel">
        <div v-if="view==='preview'" class="cover"><img src="/assets/images/proposal-cover-city.png" alt="智慧城市GIS解决方案封面"/><div class="cover-copy"><span>GIS AGENT PLATFORM</span><h2>XX市国土空间基础信息平台<br/>建设方案</h2><p>智慧自然资源 · 数字赋能 · 管理决策</p><small>XX市自然资源和规划局　2026年8月</small></div></div>
        <div v-else class="document-editor"><h2>{{proposal?.sections.find(s=>s.id===activeSection)?.title}}</h2><textarea class="tech-textarea" :value="proposal?.sections.find(s=>s.id===activeSection)?.content||'点击“生成本节内容”由 DeepSeek 基于已确认的知识依据生成。'"/><div class="citation-note">引用依据：[1] GIS平台总体架构设计规范　[2] 自然资源一张图建设解决方案　[3] 历史项目案例</div><button class="primary-button"><IconSparkles :size="16"/>生成本节内容</button></div>
        <footer><span>第 1 / 32 页</span><div><button>‹</button><button>›</button></div><span>自动保存于 10:42</span></footer>
      </section>
      <aside class="templates tech-panel"><div class="panel-title"><span>模板选择</span><span class="secondary">5套</span></div><div v-for="(theme,i) in ['政务蓝','科技深蓝','生态绿色','规划简约','商务白']" :key="theme" :class="['template',{active:i===0}]"><img src="/assets/images/proposal-cover-city.png" alt=""/><span>{{theme}}</span></div><div class="export-list"><b>交付格式</b><button @click="exportMock('PPTX')"><IconPresentation :size="15"/>PPTX</button><button @click="exportMock('DOCX')"><IconDownload :size="15"/>DOCX</button><button @click="exportMock('PDF')"><IconFileTypePdf :size="15"/>PDF</button></div></aside>
    </div>
  </AppShell>
</template>
